using System.Text.Json; namespace GodTreeXOwais.Infrastructure; public sealed record HandoffManifest(string Format,string Project,string Mission,string[] Files,DateTimeOffset CreatedAt); public sealed class HandoffPack{public string Build(string root,string mission){var d=Path.Combine(root,".godtree","handoff");Directory.CreateDirectory(d);var files=Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories).Where(x=>!x.Contains(".git")).Take(1000).Select(x=>Path.GetRelativePath(root,x)).ToArray();var m=new HandoffManifest("godtree-handoff-v1",Path.GetFileName(root),mission,files,DateTimeOffset.Now);File.WriteAllText(Path.Combine(d,"manifest.json"),JsonSerializer.Serialize(m,new JsonSerializerOptions{WriteIndented=true}));File.WriteAllText(Path.Combine(d,"AGENT_HANDOFF.md"),$"# GodTree Handoff\n\nMission: {mission}\n\nContinue from latest validated checkpoint.\n");return d;}}